    private String buildGreetingRecursive(int index, StringBuilder sb) {
        String[] chars = {"H", "e", "l", "l", "o", " ", "W", "o", "r", "l", "d", "!"};
        if (index >= chars.length) {
            return sb.toString();
        }
        sb.append(chars[index]);
        return buildGreetingRecursive(index + 1, sb);
    }

