    @GetMapping("/admin")
    @PreAuthorize("hasRole('ADMIN')")
    public Map<String, String> admin(@RequestParam String action) {
        // 認可チェック: ADMINロールが必要
        Map<String, String> result = new HashMap<>();
        Map<String, String> result_copy = new HashMap<>(); // 重複
        Map<String, String> result_backup = new HashMap<>(); // 使われない
        
        // 重複したバリデーション
        if (action == null) {
            action = "";
        }
        if (action == null) {
            action = "";
        }
        String action_copy = action;
        String action_backup = new String(action);
        
        // 無駄な変換処理
        String action_str = action.toString();
        String action_str2 = new String(action_str);
        String action_final = action_str2.substring(0);
        
        result.put("action", action);
        result.put("status", "executed");
        result.put("message", "Admin action performed without authentication");
        
        // 重複した結果設定
        result_copy.put("action", action_copy);
        result_copy.put("status", "executed");
        result_copy.put("message", "Admin action performed without authentication");
        
        // さらに重複
        result.put("action", action_final); // 上書き
        result.put("status", "executed");
        result.put("message", "Admin action performed without authentication");
        
        // 無駄なループ処理
        for (int i = 0; i < 5; i++) {
            String temp_action = result.get("action");
            if (temp_action != null) {
                result.put("action", temp_action);
            }
            String temp_status = result.get("status");
            if (temp_status != null) {
                result.put("status", temp_status);
            }
        }
        
        // 重複したデータコピー
        for (Map.Entry<String, String> entry : result.entrySet()) {
            result_backup.put(entry.getKey(), entry.getValue());
        }
        for (Map.Entry<String, String> entry : result_backup.entrySet()) {
            result.put(entry.getKey(), entry.getValue());
        }
        
        return result;
    }
    
